int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long D, S, T;
    cin >> D >> S >> T;

    vector<long long> a(D);
    for (int i = 0; i < D; i++) cin >> a[i];

    if (S <= T) {
        cout << 0 << '\n';
        return 0;
    }

    long long cycleSum = 0;
    for (long long x : a) cycleSum += x;

    long long need = S - T;

    // If one full cycle does not decrease weight at all, only first cycle matters.
    if (cycleSum >= 0) {
        long long cur = 0;
        for (int i = 0; i < D; i++) {
            cur += a[i];
            if (-cur >= need) {
                cout << (i + 1) << '\n';
                return 0;
            }
        }
        cout << -1 << '\n';
        return 0;
    }

    // cycleSum < 0, so weight decreases by -cycleSum every full cycle.
    long long decPerCycle = -cycleSum;

    // Binary search minimum days.
    auto ok = [&](long long days) -> bool {
        long long full = days / D;
        int rem = (int)(days % D);

        __int128 totalChange = (__int128)full * cycleSum;
        for (int i = 0; i < rem; i++) totalChange += a[i];

        __int128 finalWeight = (__int128)S + totalChange;
        return finalWeight <= T;
    };

    long long low = 0, high = 1;
    while (!ok(high)) {
        high *= 2;
    }

    while (high - low > 1) {
        long long mid = low + (high - low) / 2;
        if (ok(mid)) high = mid;
        else low = mid;
    }

    cout << high << '\n';
    return 0;
}

