public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long S = fs.nextLong();
        long T = fs.nextLong();
        int D = (int) fs.nextLong();

        long[] a = new long[D];
        for (int i = 0; i < D; i++) a[i] = fs.nextLong();

        // If already at or below target
        if (S <= T) {
            System.out.println(0);
            return;
        }

        long need = S - T; // total decrease needed

        long[] pref = new long[D + 1];
        for (int i = 0; i < D; i++) {
            pref[i + 1] = pref[i] + a[i];
        }

        long cycleSum = pref[D];

        long answer = Long.MAX_VALUE;

        if (cycleSum > 0) {
            // Use full cycles, then find earliest day in next cycle
            for (int i = 1; i <= D; i++) {
                long p = pref[i];
                if (p >= need) {
                    answer = Math.min(answer, i);
                } else {
                    long rem = need - p;
                    long k = (rem + cycleSum - 1) / cycleSum; // extra full cycles needed
                    long days = k * (long) D + i;
                    answer = Math.min(answer, days);
                }
            }
            System.out.println(answer);
        } else {
            // Total decrease per cycle is non-positive, only first cycle matters
            for (int i = 1; i <= D; i++) {
                if (pref[i] >= need) {
                    answer = Math.min(answer, i);
                    break;
                }
            }
            System.out.println(answer == Long.MAX_VALUE ? -1 : answer);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

