int main() {
    long long S, T;
    int D;
    scanf("%lld %lld %d", &S, &T, &D);
    int a[D];
    for (int i = 0; i < D; i++) {
        scanf("%d", &a[i]);
    }

    if (S <= T) {
        printf("0\n");
        return 0;
    }

    long long current = S;
    long long min_weight = S;
    long long cycle_sum = 0;

    // Simulate one full cycle to see if possible
    for (int i = 0; i < D; i++) {
        current += a[i];
        if (current <= T) {
            printf("%d\n", i + 1);
            return 0;
        }
        if (current < min_weight) {
            min_weight = current;
        }
        cycle_sum += a[i];
    }

    // If net change is non-negative, impossible to go below T after first cycle
    if (cycle_sum >= 0) {
        printf("-1\n");
        return 0;
    }

    // Otherwise, we can reduce. Calculate full cycles needed.
    long long drop_per_cycle = -cycle_sum;
    long long needed_drop = S - T;
    long long cycles = (needed_drop - (S - min_weight) + drop_per_cycle - 1) / drop_per_cycle;
    if (cycles < 1) cycles = 1;

    // Simulate from after those cycles
    long long days = cycles * D;
    current = S + cycles * cycle_sum;

    // Simulate final partial cycle
    for (int i = 0; i < D; i++) {
        current += a[i];
        days++;
        if (current <= T) {
            printf("%lld\n", days);
            return 0;
        }
    }

    // Should never reach here
    printf("-1\n");
    return 0;
}

