int main() {
    long long S, T, D;
    scanf("%lld %lld %lld", &S, &T, &D);

    long long *a = malloc(D * sizeof(long long));
    for (int i = 0; i < D; i++) scanf("%lld", &a[i]);

    // Simulate first cycle
    long long w = S;
    for (int i = 0; i < D; i++) {
        w += a[i];
        if (w <= T) {
            printf("%d\n", i + 1);
            free(a);
            return 0;
        }
    }

    long long cycle_sum = w - S;
    if (cycle_sum >= 0) {
        printf("-1\n");
        free(a);
        return 0;
    }

    // Find min prefix sum within a cycle
    // We need smallest k >= 1 (additional full cycles beyond the first) such that
    // after k full cycles total, simulating hits T
    // Weight at start of cycle k+1 (0-indexed from 0) = S + k*cycle_sum
    // We need S + k*cycle_sum + prefix[i] <= T for some i
    // => k*(-cycle_sum) >= S + prefix[i] - T
    // Find min over i of (S + prefix[i] - T), need k >= ceil(that / (-cycle_sum))
    // But we want minimum k >= 1 (already checked k=1 above... wait k=1 is first cycle)
    // Actually already checked k=0 start. k=1 means after 1 full cycle.
    // k >= ceil((S + min_prefix - T) / (-cycle_sum)), k >= 1

    long long prefix = 0, min_prefix = 0;
    long long min_day = 0;
    for (int i = 0; i < D; i++) {
        prefix += a[i];
        if (prefix < min_prefix) { min_prefix = prefix; min_day = i + 1; }
    }

    long long neg_cs = -cycle_sum;
    long long need = S + min_prefix - T; // need k * neg_cs >= need
    long long k = (need + neg_cs - 1) / neg_cs;
    if (k < 1) k = 1;

    // Now simulate from weight S + k*cycle_sum
    long long start_w = S + k * cycle_sum;
    long long cur = start_w;
    for (int i = 0; i < D; i++) {
        cur += a[i];
        if (cur <= T) {
            printf("%lld\n", k * D + i + 1);
            free(a);
            return 0;
        }
    }

    printf("-1\n");
    free(a);
    return 0;
}

