int main(void) {
    long long D, S, T;
    if (scanf("%lld %lld %lld", &D, &S, &T) != 3) return 0;

    long long *a = (long long *)malloc(sizeof(long long) * D);
    for (long long i = 0; i < D; i++) scanf("%lld", &a[i]);

    if (S <= T) {
        printf("0\n");
        free(a);
        return 0;
    }

    long long prefix = 0;
    long long minPrefix = 0;
    long long ans = -1;

    for (long long i = 0; i < D; i++) {
        prefix += a[i];
        if (S + prefix <= T) {
            ans = i + 1;
            break;
        }
        if (prefix < minPrefix) minPrefix = prefix;
    }

    if (ans != -1) {
        printf("%lld\n", ans);
        free(a);
        return 0;
    }

    long long cycleSum = prefix;

    if (cycleSum >= 0) {
        printf("-1\n");
        free(a);
        return 0;
    }

    long long need = (S + minPrefix) - T;  // positive
    long long k = 0;
    if (need > 0) {
        long long dec = -cycleSum;
        k = (need + dec - 1) / dec;
    }

    long long baseWeight = S + k * cycleSum;
    prefix = 0;
    for (long long i = 0; i < D; i++) {
        prefix += a[i];
        if (baseWeight + prefix <= T) {
            ans = k * D + (i + 1);
            break;
        }
    }

    printf("%lld\n", ans);

    free(a);
    return 0;
}
